create table if not exists public.integration_connection_attempts (id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,integration_id uuid not null references public.integrations(id) on delete cascade,attempt_type text not null,status text not null default 'started',state_token text unique,redirect_uri text,provider_state text,error_message text,metadata jsonb not null default '{}',created_at timestamptz not null default now(),expires_at timestamptz,completed_at timestamptz);
create table if not exists public.integration_imports (id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,integration_id uuid not null references public.integrations(id) on delete cascade,file_name text not null,storage_path text not null,content_type text,file_size bigint not null default 0,checksum text,format text not null,status text not null default 'uploaded',row_count integer not null default 0,imported_count integer not null default 0,failed_count integer not null default 0,duplicate_count integer not null default 0,mapping jsonb not null default '{}',preview jsonb not null default '{}',errors jsonb not null default '[]',metadata jsonb not null default '{}',created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),completed_at timestamptz);
create table if not exists public.integration_import_rows (id uuid primary key default gen_random_uuid(),import_id uuid not null references public.integration_imports(id) on delete cascade,row_number integer not null,source_data jsonb not null,normalized_data jsonb not null default '{}',status text not null default 'pending',local_entity_type text,local_entity_id uuid,error_message text,content_hash text,created_at timestamptz not null default now(),unique(import_id,row_number));
create table if not exists public.integration_oauth_states (id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,integration_id uuid not null references public.integrations(id) on delete cascade,attempt_id uuid references public.integration_connection_attempts(id) on delete cascade,state_token text not null unique,provider text not null,code_verifier text,redirect_uri text not null,scopes text[] not null default '{}',status text not null default 'pending',error_message text,created_at timestamptz not null default now(),expires_at timestamptz not null,completed_at timestamptz);
insert into storage.buckets(id,name,public) values('bizstack-imports','bizstack-imports',false) on conflict(id) do nothing;
alter table public.integration_connection_attempts enable row level security; alter table public.integration_imports enable row level security; alter table public.integration_import_rows enable row level security; alter table public.integration_oauth_states enable row level security;
grant select,insert,update,delete on public.integration_connection_attempts,public.integration_imports,public.integration_import_rows,public.integration_oauth_states to authenticated;
drop policy if exists "Biz owner connection attempts" on public.integration_connection_attempts; create policy "Biz owner connection attempts" on public.integration_connection_attempts for all to authenticated using(exists(select 1 from public.businesses b where b.id=business_id and b.owner_id=auth.uid())) with check(exists(select 1 from public.businesses b where b.id=business_id and b.owner_id=auth.uid()));
drop policy if exists "Biz owner imports" on public.integration_imports; create policy "Biz owner imports" on public.integration_imports for all to authenticated using(exists(select 1 from public.businesses b where b.id=business_id and b.owner_id=auth.uid())) with check(exists(select 1 from public.businesses b where b.id=business_id and b.owner_id=auth.uid()));
drop policy if exists "Biz owner import rows" on public.integration_import_rows; create policy "Biz owner import rows" on public.integration_import_rows for all to authenticated using(exists(select 1 from public.integration_imports i join public.businesses b on b.id=i.business_id where i.id=import_id and b.owner_id=auth.uid())) with check(exists(select 1 from public.integration_imports i join public.businesses b on b.id=i.business_id where i.id=import_id and b.owner_id=auth.uid()));
drop policy if exists "Biz owner oauth states" on public.integration_oauth_states; create policy "Biz owner oauth states" on public.integration_oauth_states for all to authenticated using(exists(select 1 from public.businesses b where b.id=business_id and b.owner_id=auth.uid())) with check(exists(select 1 from public.businesses b where b.id=business_id and b.owner_id=auth.uid()));
drop policy if exists "Biz owner import objects" on storage.objects; create policy "Biz owner import objects" on storage.objects for all to authenticated using(bucket_id='bizstack-imports' and (storage.foldername(name))[1] in(select b.id::text from public.businesses b where b.owner_id=auth.uid())) with check(bucket_id='bizstack-imports' and (storage.foldername(name))[1] in(select b.id::text from public.businesses b where b.owner_id=auth.uid()));